using HakutaiKagami.Core.Messaging;
namespace HakutaiKagami.Core.Contracts;
public sealed record ActiveMilitaryInput(EntityId Id,EntityId Case);
public sealed record ActiveMilitaryAgreement(ActiveMilitaryInput Input,EntityId Previous,EntityId Principal,EntityId Agent,EntityId Owner,EntityId Site,EntityId Army,long At,long Revision,MilitaryIssuerAuthorityBasis Source);
public sealed record ActiveMilitaryState(string Policy,ActiveMilitaryAgreement[] Entries);
public static partial class NewGameMilitary
{
    public const string ActiveSuccessionContract="local-consenting-current-head-same-active-garrison-case-v1";
    static ActiveMilitaryAgreement[] ActiveAt(ContractWorld w,long at,long rev)=>w.NewMilitary?.ActiveSuccession?.Entries.Where(e=>Before(e.At,e.Revision,at,rev)).ToArray()??[];
    static ActiveMilitaryState? ActiveBefore(ActiveMilitaryState? s,long at,long rev)=>s==null||!s.Entries.Any(e=>Before(e.At,e.Revision,at,rev))?null:s with{Entries=s.Entries.Where(e=>Before(e.At,e.Revision,at,rev)).ToArray()};
    internal static IEnumerable<(long At,long Revision)> ActiveInputs(ContractWorld w)=>LedgerStates(w).SelectMany(s=>s.ActiveSuccession?.Entries.Select(e=>(e.At,e.Revision))??[]);
    public static bool ActiveAgreementIdUsed(ContractWorld w,EntityId id)=>LedgerStates(w).Any(s=>s.ActiveSuccession?.Entries.Any(e=>e.Input.Id==id)==true);
    static bool AssembledCustody(ContractWorld w,long at,long rev){var s=w.NewMilitary;return s?.Binding!=null&&s.Authority!=null&&CustodyAt(w,at,rev)&&!DeployedAt(w,at)&&AtHome(w)&&!Returning(w,at,rev)&&ArmyRoadMarch.View(w)?.Marching!=true&&!CaseRequests(w,at,rev).Any(q=>q.Input.Action==NewMilitaryAction.RequestEngagement)&&CaseRequests(w,at,rev).Where(q=>q.Message!=null).All(q=>{var m=w.Messaging.Messages.Single(m=>m.Id==q.Message);return MessageFlow.LearnedAt(w.Messaging,m.Id,m.RecipientId) is {} t&&t<=at;});}
    public static bool CanRetainActiveForSuccession(ContractWorld w,EntityId who,EntityId owner,EntityId home,long at,long rev){
        if(who!=w.PlayerControl)return false;var s=LedgerStates(w).SingleOrDefault(s=>s.Terms.Owner==owner&&s.Terms.Site==home&&CustodyAt(LedgerContext(w,s),at,rev));if(s==null)return false;
        var c=BeforeState(LedgerContext(w,s),at,rev);return AssembledCustody(c,at,rev)&&CommunityStewardship.Local(c,who,home,at,rev+1);
    }
    static ActiveMilitaryAgreement PrepareActive(ContractWorld w,ActiveMilitaryInput i,long at,long rev){
        Need(HouseSuccession.Enabled(w)&&EntityId.IsValid(i.Id.Value)&&w.NewMilitary!=null,"活動軍の引継ぎ入力ではありません");var s=w.NewMilitary!;long before=rev-1;var root=CaseStart(w,at,before);Need(root!=null&&root.Input.Id==i.Case&&AssembledCustody(w,at,before),"同じ軍務の軍を本拠へ集合し、未決書状・展開・行軍・返還を終えてください");
        var old=CasePrincipal(w,at,before);var head=HouseSuccession.Head(w,s.Terms.Owner,at,before);Need(old!=head,"この現当主との活動軍原本は確認済み、または代表者が変わっていません");
        Need(CommunityStewardship.Local(w,w.PlayerControl,s.Terms.Site,at,rev)&&CommunityStewardship.Local(w,head,s.Terms.Site,at,rev)&&!PersonalLife.Resting(w,at,before)&&!CastleAdministration.Blocked(w,s.Terms.Site,at,before)&&MemberOfGarrisonHouse(w,w.PlayerControl,s.Terms.Owner,at,before)&&(head==w.PlayerControl||w.Characters.Single(c=>c.Id==head).WillObey),"現当主と本人の現地立会い・所属・同意が必要です");
        var a=FactionStances.ResolveAuthority(w,head,s.Terms.Owner,at,before);Need(a!=null&&w.LandRights.Any(l=>l.Subject==s.Terms.Owner&&l.Target==s.Terms.Site&&l.Kind=="control"&&l.From<=at&&at<l.Until),"この家と駐屯地の実権がありません");
        var control=w.LandRights.Single(l=>l.Subject==s.Terms.Owner&&l.Target==s.Terms.Site&&l.Kind=="control"&&l.From<=at&&at<l.Until);
        var source=new MilitaryIssuerAuthorityBasis(ActiveSuccessionContract,head,w.PlayerControl,s.Terms.Owner,s.Terms.Site,a.Membership,a.Office,control.Id,null,at,before);
        return new(i,old,head,w.PlayerControl,s.Terms.Owner,s.Terms.Site,s.Terms.Army,at,rev,source);
    }
    public static bool CanAgreeActiveSuccession(ContractWorld w){if(w.NewMilitary==null||CaseStart(w)==null)return false;try{PrepareActive(w,new(new("request:active-succession-preview"),CaseStart(w)!.Input.Id),w.ElapsedSeconds,w.CommitSequence+1);return true;}catch(Exception e)when(e is InvalidDataException or InvalidOperationException ){return false;}}
    internal static void AgreeActive(ContractWorld w,ActiveMilitaryInput i){var e=PrepareActive(w,i,w.ElapsedSeconds,w.CommitSequence);w.NewMilitary=w.NewMilitary! with{ActiveSuccession=new(ActiveSuccessionContract,[..w.NewMilitary.ActiveSuccession?.Entries??[],e])};SyncAuthority(w);}
    static bool ActiveMilitaryAgreementAllows(ContractWorld w,EntityId issuer,EntityId agent,EntityId owner,EntityId site)=>w.NewMilitary is {} s&&s.Terms.Owner==owner&&s.Terms.Site==site&&agent==w.PlayerControl&&CaseStart(w) is {} q&&ActiveAt(w,w.ElapsedSeconds,w.CommitSequence).Any(e=>e.Principal==issuer&&e.Agent==agent)&&HouseSuccession.Head(w,owner)==issuer&&MemberOfGarrisonHouse(w,agent,owner,w.ElapsedSeconds,w.CommitSequence);
    static void ValidateActiveSuccession(ContractWorld w){var s=w.NewMilitary!.ActiveSuccession;if(s==null)return;Need(s.Policy==ActiveSuccessionContract&&s.Entries!=null&&s.Entries.Length>0&&s.Entries.Select(e=>e.Input.Id).Distinct().Count()==s.Entries.Length,"活動軍引継ぎの版・原本が不正です");long rev=0;foreach(var e in s.Entries){Need(e.Revision>rev&&e.Revision<=w.CommitSequence&&e.At<=w.ElapsedSeconds&&!FactionStances.OtherIdUsed(w,e.Input.Id,includeActiveMilitary:false,includeRemoteMilitary:false)&&!FactionStances.OwnIdUsed(w,e.Input.Id),"活動軍原本の順序・IDが不正です");var prior=BeforeState(w,e.At,e.Revision-1);prior.CommitSequence=e.Revision;Need((e.Source.Contract==RemoteSuccessionContract?ExpectedRemoteAgreement(w,e):PrepareActive(prior,e.Input,e.At,e.Revision))==e,"活動軍原本の現地同意・実権・時点が一致しません");rev=e.Revision;}}
    static MilitaryScopedGrant[] ActiveGrants(ContractWorld w,MilitaryScopedGrant[] original){var rows=ActiveAt(w,w.ElapsedSeconds,w.CommitSequence);if(rows.Length==0)return original;var result=new List<MilitaryScopedGrant>();foreach(var g in original){var changes=rows.Where(e=>e.Input.Case==g.Case).ToArray();if(changes.Length==0){result.Add(g);continue;}var first=changes[0];result.Add(g with{Mandate=g.Mandate with{Until=first.At},UntilRevision=first.Revision});for(int n=0;n<changes.Length;n++){var e=changes[n];var next=n+1<changes.Length?changes[n+1]:null;var mandate=g.Mandate with{Id=new("mandate:active-succession/"+Hash(e.Input.Id.Value)),Principal=e.Principal,From=e.At,Until=next?.At??g.Mandate.Until};result.Add(new(g.Case,g.Owner,mandate,e.Revision,next?.Revision??g.UntilRevision));}}return result.ToArray();}
}
public sealed partial class WorldSession
{
    public bool CanAgreeActiveMilitary(){lock(gate)return NewGameMilitary.CanAgreeActiveSuccession(state);}
    public CommandResult AgreeActiveMilitary(ActiveMilitaryInput i,EntityId actor,long revision){lock(gate){if(actor!=state.PlayerControl)return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,"本人の活動軍確認ではありません");var old=NewGameMilitary.LedgerStates(state).SelectMany(s=>s.ActiveSuccession?.Entries??[]).SingleOrDefault(e=>e.Input.Id==i.Id);if(old!=null)return new(old.Input==i?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"受付済みです");if(FactionStances.OtherIdUsed(state,i.Id)||FactionStances.OwnIdUsed(state,i.Id))return new(ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"別の原本です");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,i.Id,state.CommitSequence,"表示を更新してください");try{Change(w=>NewGameMilitary.AgreeActive(w,i));return new(ResultCode.Accepted,i.Id,state.CommitSequence,"同じ軍の指揮原本を現当主と確認しました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,e.Message);}}}
}
